import 'package:flutter/material.dart';
import 'dart:math' as math;

class MyCirclePainter extends CustomPainter {
  final Color color;

  MyCirclePainter({this.color = Colors.blue});

  @override
  void paint(Canvas canvas, Size size) {
    final Paint paint = Paint()
      ..color = color
      ..style = PaintingStyle.fill;

    final Offset center = Offset(size.width / 2, size.height / 2);
    final double radius = math.min(size.width / 2, size.height / 2);

    canvas.drawCircle(center, radius, paint);
  }

  @override
  bool shouldRepaint(covariant MyCirclePainter oldDelegate) {
    return oldDelegate.color != color;
  }
}

class MyCustomDrawing extends StatelessWidget {
  const MyCustomDrawing({Key? key}) : super(key: key);

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text('Custom Paint Demo')),
      body: Center(
        child: CustomPaint(
          size: Size(200, 200),
          painter: MyCirclePainter(color: Colors.orangeAccent),
        ),
      ),
    );
  }
}

