import 'package:flutter/material.dart';
import 'dart:math' as math;

class PieSlicePainter extends CustomPainter {
  final double startAngle;
  final double sweepAngle;
  final Color color;
  final double strokeWidth;
  final PaintingStyle paintingStyle;

  PieSlicePainter({
    required this.startAngle,
    required this.sweepAngle,
    required this.color,
    this.strokeWidth = 0,
    this.paintingStyle = PaintingStyle.fill,
  });

  @override
  void paint(Canvas canvas, Size size) {
    final Paint paint = Paint()
      ..color = color
      ..style = paintingStyle;

    if (paintingStyle == PaintingStyle.stroke) {
      paint.strokeWidth = strokeWidth;
    }

    final Rect rect = Rect.fromLTWH(0, 0, size.width, size.height);

    canvas.drawArc(
      rect,
      startAngle,
      sweepAngle,
      true,
      paint,
    );
  }

  @override
  bool shouldRepaint(covariant PieSlicePainter oldDelegate) {
    return oldDelegate.startAngle != startAngle ||
        oldDelegate.sweepAngle != sweepAngle ||
        oldDelegate.color != color ||
        oldDelegate.strokeWidth != strokeWidth ||
        oldDelegate.paintingStyle != paintingStyle;
  }
}

class MyPieChartDemo extends StatelessWidget {
  const MyPieChartDemo({Key? key}) : super(key: key);

  @override
  Widget build(BuildContext context) {
    return Center(
      child: CustomPaint(
        size: Size(150, 150),
        painter: PieSlicePainter(
          startAngle: -math.pi / 2,
          sweepAngle: math.pi / 2,
          color: Colors.redAccent,
        ),
      ),
    );
  }
}
